INSERT OR REPLACE INTO posts (id,user_id,username,title,description,hashtags,tokens_prompt,tokens_save,tokens_autopost,carousel_data,created_at,chat_history,likes_count,is_liked,is_shared) VALUES ('p_062bb438','u1','Roi Chocron','ALPINE REALMS: A DUALITY OF SEASONS','An editorial exploration of Alpine landscape transitions between summer and winter, presented with avant-garde visual design principles.','#AlpineLandscapes #SeasonalChange #AvantGardeDesign #UIUX #Editorial',1533,513,0,'{"id":"p_062bb438","author_name":"Roi Chocron","created_at":"2026-08-26T20:00:22.088Z","description":"An editorial exploration of Alpine landscape transitions between summer and winter, presented with avant-garde visual design principles.","hashtags":"#AlpineLandscapes #SeasonalChange #AvantGardeDesign #UIUX #Editorial","slides":[{"slide_index":0,"tag":"THE SHIFT","title":"ALPINE REALMS: A DUALITY OF SEASONS","background_style":"background-color: #0A1128;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"font-family: ''Heebo'', sans-serif; width: 540px; height: 540px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: flex-start; align-items: flex-start; padding: 60px 40px; color: #FFFFFF; \"><h1 style=\"font-size: 36px; line-height: 1.0; letter-spacing: -0.03em; margin: 0; padding: 0; font-weight: 900;\">SUMMER''S VERDANT DOMAIN</h1><p style=\"font-size: 18px; line-height: 1.3; margin-top: 30px; max-width: 400px; color: #E0E0E0;\">Summer transforms alpine terrains into vibrant ecosystems. Lush meadows blanket the slopes, punctuated by diverse flora. Crystalline streams carve paths through rock and soil, fed by snowmelt. The air is crisp, carrying the scent of pine and wildflowers.</p><div style=\"position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none;\"><div style=\"position: absolute; top: 50%; left: 60%; transform: translate(-50%, -50%) rotate(15deg); width: 200px; height: 200px; background: radial-gradient(circle, rgba(0,255,194,0.3) 0%, rgba(0,255,194,0) 70%);\"></div></div></div>"},{"slide_index":1,"tag":"THE TRANSFORMATION","title":"WINTER''S FROZEN STILLNESS","background_style":"background-color: #00FFC2;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"font-family: ''Heebo'', sans-serif; width: 540px; height: 540px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: flex-end; align-items: flex-end; padding: 40px 40px 60px 40px; color: #0A1128;\"><h1 style=\"font-size: 32px; line-height: 1.1; letter-spacing: -0.02em; margin: 0; padding: 0; font-weight: 700; text-align: right;\">THE WHITE IMMENSITY</h1><p style=\"font-size: 17px; line-height: 1.3; margin-top: 25px; max-width: 400px; color: #0A1128; text-align: right;\">Winter redefines these altitudes entirely. Snow blankets everything in a pristine, uniform layer, obscuring the subtle details of summer. The landscape becomes stark, geometric, dominated by the raw structure of rock faces and peaks. Silence reigns, broken only by the wind.</p><div style=\"position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none;\"><div style=\"position: absolute; bottom: 20%; right: 20%; width: 300px; height: 300px; background: repeating-linear-gradient(45deg, #0A1128, #0A1128 5px, rgba(10, 17, 40, 0.5) 5px, rgba(10, 17, 40, 0.5) 10px); box-shadow: -8px -8px 0px #0A1128;\"></div></div></div>"},{"slide_index":2,"tag":"THE CONTRAST","title":"LIFE AND STILLNESS","background_style":"background-color: #E0E0E0;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"font-family: ''Heebo'', sans-serif; width: 540px; height: 540px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: center; align-items: center; padding: 40px; color: #0A1128;\"><div style=\"width: 450px; height: 450px; border: 3px solid #00FFC2; padding: 30px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center;\"><h1 style=\"font-size: 42px; line-height: 1.0; letter-spacing: -0.04em; margin: 0; padding: 0; font-weight: 900; color: #0A1128;\">DIVERGENCE & UNITY</h1><p style=\"font-size: 18px; line-height: 1.3; margin-top: 30px; color: #0A1128;\">Summer thrives with organic abundance, a riot of life and color. Winter presents a severe, elemental beauty, emphasizing form and structure. Both states possess a profound, distinct majesty, showcasing the dynamic yet enduring character of the high alpine environment.</p></div></div>"}]}','2026-08-26 20:00:22','[{"role":"user","content":"תיצור לי פוסט קרוסלה שמסביר מה ההבדל בין סוגי הנופים של האלפים בקיץ ובחורף עם תמונות רפרנס"},{"role":"assistant","content":"{\n  \"id\": \"a1b2c3d4-e5f6-7890-1234-567890abcdef\",\n  \"author_name\": \"AvantGarde UI/UX\",\n  \"created_at\": \"2024-03-15T10:30:00.000Z\",\n  \"tokens_used\": 450,\n  \"description\": \"An editorial exploration of Alpine landscape transitions between summer and winter, presented with avant-garde visual design principles.\",\n  \"hashtags\": \"#AlpineLandscapes #SeasonalChange #AvantGardeDesign #UIUX #Editorial\",\n  \"slides\": [\n    {\n      \"slide_index\": 0,\n      \"tag\": \"THE SHIFT\",\n      \"title\": \"ALPINE REALMS: A DUALITY OF SEASONS\",\n      \"background_style\": \"background-color: #0A1128;\",\n      \"html_content\": \"<link href=\\\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\\\" rel=\\\"stylesheet\\\"><div style=\\\"font-family: ''Heebo'', sans-serif; width: 540px; height: 540px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: flex-start; align-items: flex-start; padding: 60px 40px; color: #FFFFFF; \\\"><h1 style=\\\"font-size: 36px; line-height: 1.0; letter-spacing: -0.03em; margin: 0; padding: 0; font-weight: 900;\\\">SUMMER''S VERDANT DOMAIN</h1><p style=\\\"font-size: 18px; line-height: 1.3; margin-top: 30px; max-width: 400px; color: #E0E0E0;\\\">Summer transforms alpine terrains into vibrant ecosystems. Lush meadows blanket the slopes, punctuated by diverse flora. Crystalline streams carve paths through rock and soil, fed by snowmelt. The air is crisp, carrying the scent of pine and wildflowers.</p><div style=\\\"position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none;\\\"><div style=\\\"position: absolute; top: 50%; left: 60%; transform: translate(-50%, -50%) rotate(15deg); width: 200px; height: 200px; background: radial-gradient(circle, rgba(0,255,194,0.3) 0%, rgba(0,255,194,0) 70%);\\\"></div></div></div>\"\n    },\n    {\n      \"slide_index\": 1,\n      \"tag\": \"THE TRANSFORMATION\",\n      \"title\": \"WINTER''S FROZEN STILLNESS\",\n      \"background_style\": \"background-color: #00FFC2;\",\n      \"html_content\": \"<link href=\\\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\\\" rel=\\\"stylesheet\\\"><div style=\\\"font-family: ''Heebo'', sans-serif; width: 540px; height: 540px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: flex-end; align-items: flex-end; padding: 40px 40px 60px 40px; color: #0A1128;\\\"><h1 style=\\\"font-size: 32px; line-height: 1.1; letter-spacing: -0.02em; margin: 0; padding: 0; font-weight: 700; text-align: right;\\\">THE WHITE IMMENSITY</h1><p style=\\\"font-size: 17px; line-height: 1.3; margin-top: 25px; max-width: 400px; color: #0A1128; text-align: right;\\\">Winter redefines these altitudes entirely. Snow blankets everything in a pristine, uniform layer, obscuring the subtle details of summer. The landscape becomes stark, geometric, dominated by the raw structure of rock faces and peaks. Silence reigns, broken only by the wind.</p><div style=\\\"position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none;\\\"><div style=\\\"position: absolute; bottom: 20%; right: 20%; width: 300px; height: 300px; background: repeating-linear-gradient(45deg, #0A1128, #0A1128 5px, rgba(10, 17, 40, 0.5) 5px, rgba(10, 17, 40, 0.5) 10px); box-shadow: -8px -8px 0px #0A1128;\\\"></div></div></div>\"\n    },\n    {\n      \"slide_index\": 2,\n      \"tag\": \"THE CONTRAST\",\n      \"title\": \"LIFE AND STILLNESS\",\n      \"background_style\": \"background-color: #E0E0E0;\",\n      \"html_content\": \"<link href=\\\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\\\" rel=\\\"stylesheet\\\"><div style=\\\"font-family: ''Heebo'', sans-serif; width: 540px; height: 540px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: center; align-items: center; padding: 40px; color: #0A1128;\\\"><div style=\\\"width: 450px; height: 450px; border: 3px solid #00FFC2; padding: 30px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center;\\\"><h1 style=\\\"font-size: 42px; line-height: 1.0; letter-spacing: -0.04em; margin: 0; padding: 0; font-weight: 900; color: #0A1128;\\\">DIVERGENCE & UNITY</h1><p style=\\\"font-size: 18px; line-height: 1.3; margin-top: 30px; color: #0A1128;\\\">Summer thrives with organic abundance, a riot of life and color. Winter presents a severe, elemental beauty, emphasizing form and structure. Both states possess a profound, distinct majesty, showcasing the dynamic yet enduring character of the high alpine environment.</p></div></div>\"\n    }\n  ]\n}"}]',0,0,0);
INSERT OR REPLACE INTO posts (id,user_id,username,title,description,hashtags,tokens_prompt,tokens_save,tokens_autopost,carousel_data,created_at,chat_history,likes_count,is_liked,is_shared) VALUES ('p_5aa88dbd','u1','Roi Chocron','אמנות הלוח.','An editorial exploration into the varied landscape of skateboard types, presented with avant-garde typographic and layout principles. This carousel dissects the essential distinctions between various decks, catering to both novice enthusiasts and seasoned riders.','#סקייטבורד #סוגיסקייטבורד #תרבותסקייט #ציודסקייט',1888,628,0,'{"id":"p_5aa88dbd","author_name":"Roi Chocron","created_at":"2026-08-26T20:32:29.617Z","description":"An editorial exploration into the varied landscape of skateboard types, presented with avant-garde typographic and layout principles. This carousel dissects the essential distinctions between various decks, catering to both novice enthusiasts and seasoned riders.","hashtags":"#סקייטבורד #סוגיסקייטבורד #תרבותסקייט #ציודסקייט","slides":[{"slide_index":0,"tag":"הקדמה","title":"אמנות הלוח.","background_style":"background-color: #0A0A0A;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"width: 100%; height: 100%; box-sizing: border-box; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; padding: 50px 40px 60px 40px; position: relative;\"><img src=\"/uploads/img_1787776342551_306.png\" style=\"position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0.15; z-index: 1;\"><div style=\"position: relative; z-index: 2; width: 100%; max-width: 450px;\"><h1 style=\"font-family: ''Heebo'', sans-serif; font-size: 58px; line-height: 0.9; letter-spacing: -0.06em; color: #F0F0F0; margin: 0 0 20px 0; font-weight: 900;\">הבנת הלוח.</h1><p style=\"font-family: ''Heebo'', sans-serif; font-size: 16px; line-height: 1.6; color: #AAAAAA; margin: 0;\">הסוגים השונים של סקייטבורדים קיימים כדי לשרת מטרות ספציפיות. מבנה הלוח, הגודל והרכיבים משפיעים באופן דרמטי על חווית הרכיבה. גלה את ההבדלים שיעזרו לך לבחור את הלוח המושלם.</p></div></div>"},{"slide_index":1,"tag":"לונגבורד","title":"כוח המשיכה.","background_style":"background-color: #E6007E;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"width: 100%; height: 100%; box-sizing: border-box; display: flex; flex-direction: column; justify-content: flex-start; align-items: flex-start; padding: 60px 40px 50px 40px; position: relative; overflow: hidden;\"><h1 style=\"font-family: ''Heebo'', sans-serif; font-size: 62px; line-height: 0.95; letter-spacing: -0.05em; color: #0A0A0A; margin: 0; font-weight: 900; text-transform: uppercase;\">לונגבורד</h1><div style=\"width: 70%; margin-top: 20px; border-top: 4px solid #0A0A0A; padding-top: 20px;\"><p style=\"font-family: ''Heebo'', sans-serif; font-size: 16px; line-height: 1.6; color: #0A0A0A; margin: 0;\">שטיפה מוחלטת של הבסיס. הגרסאות הארוכות הללו, המיועדות בעיקר לניידות, קרוזינג וגלישה במורדות, מציעות יציבות ומרחב תנועה גדולים יותר. קצוות מעוגלים וגלגלים רכים מבטיחים רכיבה חלקה על פני מגוון משטחים, ומאפשרים שליטה אופטימלית.</p></div><div style=\"position: absolute; bottom: 0; right: -50px; width: 200px; height: 200px; background-color: #0A0A0A; box-shadow: -10px -10px 0px #F0F0F0; border-radius: 0;\"></div></div>"},{"slide_index":2,"tag":"דק ריק","title":"הבסיס.","background_style":"background-color: #F0F0F0;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"width: 100%; height: 100%; box-sizing: border-box; display: flex; flex-direction: column; justify-content: center; align-items: center; position: relative;\"><div style=\"width: 85%; margin: 0 auto; text-align: center; position: relative; z-index: 2;\"><h1 style=\"font-family: ''Heebo'', sans-serif; font-size: 50px; line-height: 1; letter-spacing: -0.05em; color: #0A0A0A; margin: 0 0 30px 0; font-weight: 900;\">דק ריק</h1><p style=\"font-family: ''Heebo'', sans-serif; font-size: 18px; line-height: 1.6; color: #0A0A0A; margin: 0;\">היסוד לכל סקייטבורד. ה-Deck הוא החלק המרכזי, הקשיח, עליו אתה עומד. הוא מגיע במגוון רוחבים ואורכים, המשפיעים על היציבות והתגובה. צורתו - מ-popsicle קלאסי ועד pintail ארוך - מכתיבה את סגנון הרכיבה.</p></div><div style=\"position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%) rotate(45deg); width: 250px; height: 250px; background: linear-gradient(135deg, #E6007E, #FFD700); opacity: 0.5; filter: blur(30px); z-index: 1;\"></div></div>"},{"slide_index":3,"tag":"סקייט טכני","title":"זריזות.","background_style":"background-color: #1A1A1A;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"width: 100%; height: 100%; box-sizing: border-box; display: flex; flex-direction: column; justify-content: flex-end; align-items: flex-end; padding: 50px 40px 60px 40px; position: relative;\"><h1 style=\"font-family: ''Heebo'', sans-serif; font-size: 55px; line-height: 1; letter-spacing: -0.06em; color: #FFD700; margin: 0 0 20px 0; font-weight: 900; text-align: right;\">סקייט טכני</h1><div style=\"width: 90%; max-width: 400px;\"><p style=\"font-family: ''Heebo'', sans-serif; font-size: 16px; line-height: 1.6; color: #CCCCCC; margin: 0; text-align: right;\">הנשמה של הפארק. סקייטבורדים אלו, קצרים וסימטריים עם זנב אף, מתוכננים לביצוע תרגילים טכניים, פליפים ושימוש ברמפות. הרוחב הקומפקטי שלהם מאפשר תמרון מהיר, מה שהופך אותם לבחירה אידיאלית עבור טריק-ריידרים.</p></div><div style=\"position: absolute; top: 0; left: 0; width: 100px; height: 100px; background-color: #FFD700; border: 3px solid #F0F0F0; box-shadow: 5px 5px 0px #F0F0F0; transform: rotate(45deg);\"></div></div>"}]}','2026-08-26 20:32:29','[{"role":"user","content":"[Attached Image URL: /uploads/img_1787776342551_306.png]\n\nתיצור פוסט שמסביר על סוגי הסקטבורדים, תשתמש בתמונה הזאת בשקופית הראשונה"},{"role":"assistant","content":"✅ I created a new carousel for you! You can preview it here, and it has been saved to your feed."},{"role":"user","content":"אני רוצה שהתמונה לא תהיה מושחרת, אפשר להקטין אותה מעט אם צריך ובגלל שהפוסט בעברית הטקסט צריך להיות צמוד לימין."},{"role":"assistant","content":"{\"type\": \"image_plan\", \"images\": [{\"description\": \"The user wants the attached image to be used on the first slide, un-darkened, possibly scaled down if needed. The carousel is in Hebrew, so text needs to be right-aligned.\"}]}"}]',0,0,0);
INSERT OR REPLACE INTO posts (id,user_id,username,title,description,hashtags,tokens_prompt,tokens_save,tokens_autopost,carousel_data,created_at,chat_history,likes_count,is_liked,is_shared) VALUES ('p_1da80f9d','u_ea2b4849','check','מה ההבדל?','השוואה בין בונה אתרים למעצב אתרים','#בונה_אתרים #מעצב_אתרים #UIUX',1329,887,1200,'{"id":"p_1da80f9d","author_name":"check","created_at":"2026-09-11T07:32:19.769Z","description":"השוואה בין בונה אתרים למעצב אתרים","hashtags":"#בונה_אתרים #מעצב_אתרים #UIUX","slides":[{"slide_index":0,"tag":"בונה אתרים vs מעצב אתרים","title":"מה ההבדל?","background_style":"background:#0A0A0A;","html_content":"<link href=''https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap'' rel=''stylesheet''><div style=''position:relative;width:100%;height:100%;box-sizing:border-box;background:#0A0A0A;color:#F5F5F5;font-family:\"Heebo\",sans-serif;direction:rtl;text-align:right;overflow:hidden;''><div style=''position:absolute;top:0;left:0;width:60%;height:100%;padding:40px;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;''><div style=''display:inline-block;background:#FF00FF;color:#0A0A0A;padding:4px 8px;font-weight:700;font-size:14px;margin-bottom:12px;''>בונה אתרים vs מעצב אתרים</div><h1 style=''font-weight:900;font-size:36px;letter-spacing:-0.05em;line-height:0.95;margin:0 0 20px;''>מה ההבדל?</h1><p style=''font-weight:400;font-size:18px;line-height:1.5;margin:0;''>הבדל מהותי בין שני התפקידים טמון בהיקף האחריות ובכלים בהם הם משתמשים. בונה אתרים מתמקד בהטמעת פתרונות טכניים, בעוד שמעצב אתרים אחראי על החוויה החזותית והאסטרטגיה של המותג. שניהם משלימים זה את זה בתהליך הפיתוח.</p></div><div style=''position:absolute;top:0;right:0;width:40%;height:100%;background:#FF00FF;clip-path:polygon(0 0,100% 0,80% 100%,0 100%);''></div></div>"},{"slide_index":1,"tag":"בונה אתרים","title":"מה זה בונה אתרים?","background_style":"background:#FF00FF;","html_content":"<link href=''https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap'' rel=''stylesheet''><div style=''position:relative;width:100%;height:100%;box-sizing:border-box;background:#FF00FF;color:#0A0A0A;font-family:\"Heebo\",sans-serif;direction:rtl;text-align:right;overflow:hidden;''><div style=''position:absolute;bottom:0;left:0;width:100%;height:40%;padding:30px;box-sizing:border-box;box-shadow:6px 6px 0px #0A0A0A;border:3px solid #0A0A0A;''><div style=''display:inline-block;background:#0A0A0A;color:#FF00FF;padding:4px 8px;font-weight:700;font-size:14px;margin-bottom:12px;''>בונה אתרים</div><h1 style=''font-weight:900;font-size:30px;letter-spacing:-0.05em;line-height:0.95;margin:0 0 16px;''>מה זה בונה אתרים?</h1><p style=''font-weight:400;font-size:18px;line-height:1.5;margin:0;''>בונה אתרים עובד בעיקר עם פלטפורמות כמו Wix, Squarespace או WordPress, שם הוא מגדיר מבנה, מוסיף תכנים ומקדם ביצועים בסיסיים. עבודתו דורשת ידע ב-HTML, CSS בסיסי ובהבנת זרימת משתמש, אך ללא צורך בעיצוב גרפי מורכב.</p></div></div>"},{"slide_index":2,"tag":"מעצב אתרים","title":"מה זה מעצב אתרים?","background_style":"background:#F5F5F5;","html_content":"<link href=''https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap'' rel=''stylesheet''><div style=''position:relative;width:100%;height:100%;box-sizing:border-box;background:#F5F5F5;color:#0A0A0A;font-family:\"Heebo\",sans-serif;direction:rtl;text-align:right;overflow:hidden;''><div style=''position:absolute;top:0;left:0;width:60%;height:100%;padding:0 80px 0 0;box-sizing:border-box;''><div style=''display:inline-block;background:#FF00FF;color:#0A0A0A;padding:4px 8px;font-weight:700;font-size:14px;margin-bottom:12px;''>מעצב אתרים</div><h1 style=''font-weight:900;font-size:32px;letter-spacing:-0.05em;line-height:0.95;margin:0 0 16px;''>מה זה מעצב אתרים?</h1><p style=''font-weight:400;font-size:18px;line-height:1.5;margin:0;''>מעצב אתרים מתמקד באפיונון חזותי, בחירת טיפוגרפיה, צבעים ואייקונים שמייצרים זהות מותגית אחידה. הוא משתמש בכלי גרפיקה כמו Figma או Adobe XD כדי לייצר מאקטים אינטראקטיביים ולבדוק את הזרימה לפני פיתוח. תפקידו לגשר בין אסתטיקה לפונקציונליות.</p></div><div style=''position:absolute;top:0;right:0;width:8px;height:100%;background:#FF00FF;''></div></div>"}]}','2026-09-11 07:32:19','[{"role":"user","content":"תיצור קרוסלה שמסבירה מה ההבדל בין בונה אתרים למעצב אתרים"},{"role":"assistant","content":"{\n  \"id\": \"a3f9c2e1-7b4d-4f9a-8c2e-5b6a9d0e1f2c\",\n  \"author_name\": \"Avante Garde Studio\",\n  \"created_at\": \"2025-09-26T12:34:56.789Z\",\n  \"tokens_used\": 260,\n  \"description\": \"השוואה בין בונה אתרים למעצב אתרים\",\n  \"hashtags\": \"#בונה_אתרים #מעצב_אתרים #UIUX\",\n  \"slides\": [\n    {\n      \"slide_index\": 0,\n      \"tag\": \"בונה אתרים vs מעצב אתרים\",\n      \"title\": \"מה ההבדל?\",\n      \"background_style\": \"background:#0A0A0A;\",\n      \"html_content\": \"<link href=''https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap'' rel=''stylesheet''><div style=''position:relative;width:100%;height:100%;box-sizing:border-box;background:#0A0A0A;color:#F5F5F5;font-family:\\\"Heebo\\\",sans-serif;direction:rtl;text-align:right;overflow:hidden;''><div style=''position:absolute;top:0;left:0;width:60%;height:100%;padding:40px;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;''><div style=''display:inline-block;background:#FF00FF;color:#0A0A0A;padding:4px 8px;font-weight:700;font-size:14px;margin-bottom:12px;''>בונה אתרים vs מעצב אתרים</div><h1 style=''font-weight:900;font-size:36px;letter-spacing:-0.05em;line-height:0.95;margin:0 0 20px;''>מה ההבדל?</h1><p style=''font-weight:400;font-size:18px;line-height:1.5;margin:0;''>הבדל מהותי בין שני התפקידים טמון בהיקף האחריות ובכלים בהם הם משתמשים. בונה אתרים מתמקד בהטמעת פתרונות טכניים, בעוד שמעצב אתרים אחראי על החוויה החזותית והאסטרטגיה של המותג. שניהם משלימים זה את זה בתהליך הפיתוח.</p></div><div style=''position:absolute;top:0;right:0;width:40%;height:100%;background:#FF00FF;clip-