tion:ltr; background-color: #EAEAEA;\\\"><div style=\\\"position:absolute; top:0; left:0; width:100%; height:60%; background-color: #EAEAEA; display:flex; justify-content:center; align-items:center;\\\"><img src=\\\"/uploads/gen_svg_1789125434808_2_625.svg\\\" style=\\\"width:100%; height:100%; object-fit:cover; mix-blend-mode:multiply; opacity:0.8;\\\"/></div><div style=\\\"position:absolute; bottom:0; left:0; width:100%; height:40%; padding:30px 40px; box-sizing:border-box; display:flex; flex-direction:column; justify-content:flex-end; background-color:#EAEAEA;\\\"><span style=\\\"font-size:16px; font-weight:700; color:#F50057; text-transform:uppercase; margin-bottom:10px; letter-spacing:0.05em;\\\">UX & INTERFACE</span><h1 style=\\\"font-size:48px; font-weight:900; color:#0F1A2B; line-height:0.95; letter-spacing:-0.05em; margin:0 0 15px 0;\\\">The Human-AI Interface</h1><p style=\\\"font-size:17px; font-weight:400; color:#0F1A2B; line-height:1.4; margin:0;\\\">Design AI for augmentative, not autonomous, operation. User experience is compromised when human agency is undermined. Implement clear feedback loops, allowing continuous human oversight and intervention. Transparency in decision-making processes builds user trust and system resilience.</p><div style=\\\"position:absolute; bottom:20px; right:30px; font-size:120px; font-weight:900; color:rgba(15,26,43,0.1); line-height:1; pointer-events:none;\\\">03</div></div></div>\"\n    }\n  ]\n}"}]',0,0,0);
INSERT OR REPLACE INTO posts (id,user_id,username,title,description,hashtags,tokens_prompt,tokens_save,tokens_autopost,carousel_data,created_at,chat_history,likes_count,is_liked,is_shared) VALUES ('p_8cf7d20d','u1','Roi Chocron','NEURAL INTERSECTIONS','A stark exploration of AI''s abstract mechanics and its conceptual interface with human intellect. Designed for clarity and impact.','#AI #ArtificialIntelligence #Design #Technology #AvantGarde',1882,897,0,'{"id":"p_8cf7d20d","author_name":"Roi Chocron","created_at":"2026-09-11T11:18:59.577Z","description":"A stark exploration of AI''s abstract mechanics and its conceptual interface with human intellect. Designed for clarity and impact.","hashtags":"#AI #ArtificialIntelligence #Design #Technology #AvantGarde","slides":[{"slide_index":0,"tag":"Core Mechanics","title":"NEURAL INTERSECTIONS","background_style":"background-color: #0d0d0d; color: #f0f0f0;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"width:100%; height:100%; box-sizing:border-box; padding: 30px; font-family: ''Heebo'', sans-serif; background-color: #0d0d0d; color: #f0f0f0; display: flex; flex-direction: column; justify-content: space-between; position: relative; overflow: hidden;\"><img src=\"/uploads/gen_1789125533105_0_642.jpg\" style=\"position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0.15; z-index: 1;\"><div style=\"position: relative; z-index: 2;\"><h1 style=\"font-size: 42px; font-weight: 900; line-height: 0.9; letter-spacing: -0.05em; margin-bottom: 20px;\">NEURAL INTERSECTIONS</h1><p style=\"font-size: 16px; line-height: 1.6; margin-top: 20px; max-width: 450px;\">Observe the intricate pathways. AI is not magic; it is a sophisticated construction of interconnected logic gates processing vast data streams. Understand its foundational architecture to harness its potential effectively.</p></div></div>"},{"slide_index":1,"tag":"Data Flow","title":"THE DATA CURRENT","background_style":"background-color: #FF6600; color: #0d0d0d;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"width:100%; height:100%; box-sizing:border-box; padding: 30px; font-family: ''Heebo'', sans-serif; background-color: #FF6600; color: #0d0d0d; display: flex; flex-direction: column; justify-content: space-between; position: relative; overflow: hidden;\"><img src=\"/uploads/gen_1789125533380_1_827.jpg\" style=\"position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0.2; mix-blend-mode: multiply; z-index: 1;\"><div style=\"position: relative; z-index: 2;\"><h1 style=\"font-size: 38px; font-weight: 700; line-height: 1.0; letter-spacing: -0.03em; margin-bottom: 15px;\">THE DATA CURRENT</h1><p style=\"font-size: 17px; line-height: 1.7; margin-top: 15px; max-width: 480px;\">Every AI decision is a consequence of the data it ingests. Its trajectory is defined by the quality, quantity, and inherent biases within the information provided. A clean current yields a pure output. Contamination leads to deviation.</p></div></div>"},{"slide_index":2,"tag":"Human-AI Interface","title":"SYNAPTIC BRIDGE","background_style":"background-color: #0f2a2a; color: #d4ffd4;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"width:100%; height:100%; box-sizing:border-box; padding: 30px; font-family: ''Heebo'', sans-serif; background-color: #0f2a2a; color: #d4ffd4; display: flex; flex-direction: column; justify-content: flex-end; position: relative; overflow: hidden;\"><img src=\"/uploads/gen_1789125533962_2_554.jpg\" style=\"position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0.1; z-index: 1;\"><div style=\"position: relative; z-index: 2; text-align: right;\"><h1 style=\"