INSERT OR REPLACE INTO posts (id,user_id,username,title,description,hashtags,tokens_prompt,tokens_save,tokens_autopost,carousel_data,created_at,chat_history,likes_count,is_liked,is_shared) VALUES ('p_8273ac5a','u_ea2b4849','check','Apple Tree','A stark, typographically driven exploration of botanical divergence, contrasting the arboreal apple with the herbaceous banana plant.','#BotanicalDivergence #ArborealVsHerbaceous #NeoBrutalism #AvantGardeDesign',1933,519,0,'{"id":"p_8273ac5a","author_name":"check","created_at":"2026-09-14T05:02:02.060Z","description":"A stark, typographically driven exploration of botanical divergence, contrasting the arboreal apple with the herbaceous banana plant.","hashtags":"#BotanicalDivergence #ArborealVsHerbaceous #NeoBrutalism #AvantGardeDesign","slides":[{"slide_index":0,"tag":"Arboreal","title":"Apple Tree","background_style":"background-color: #121212; color: #E0E0E0; font-family: ''Heebo'', sans-serif;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"width:100%; height:100%; box-sizing:border-box; padding: 40px; display: flex; flex-direction: column; justify-content: space-between; align-items: flex-start;\"><h1 style=\"font-size: 48px; line-height: 0.9; letter-spacing: -0.05em; margin: 0; color: #FF5722;\">The Apple Tree</h1><p style=\"font-size: 18px; line-height: 1.5; max-width: 400px;\">A true tree, originating from a seed, developing a woody trunk and branches. Its life cycle is measured in decades, producing fruit annually from a persistent, dormant state.</p><div style=\"width: 100%; text-align: right; font-size: 14px; color: #757575;\">Slide 1/2</div></div>"},{"slide_index":1,"tag":"Herbaceous","title":"Banana Plant","background_style":"background-color: #FF5722; color: #121212; font-family: ''Heebo'', sans-serif;","html_content":"<link href=\"https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;700;900&display=swap\" rel=\"stylesheet\"><div style=\"width:100%; height:100%; box-sizing:border-box; padding: 40px; display: flex; flex-direction: column; justify-content: flex-start; align-items: center; position: relative;\"><img src=\"/uploads/gen_1789362118445_0_727.jpg\" style=\"position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 80%; height: auto; object-fit: cover; opacity: 0.3; box-shadow: 6px 6px 0px #121212;\"><h1 style=\"font-size: 52px; line-height: 0.9; letter-spacing: -0.05em; margin: 0; position: relative; z-index: 1; text-align: center;\">Banana Plant</h1><p style=\"font-size: 18px; line-height: 1.5; max-width: 400px; position: relative; z-index: 1; margin-top: 20px; text-align: center;\">Technically a giant herb, not a tree. Its ''trunk'' is a pseudostem formed by rolled leaves. It dies after fruiting, with new growth emerging from the rhizome.</p><div style=\"width: 100%; text-align: left; font-size: 14px; color: #424242; margin-top: auto; position: relative; z-index: 1;\">Slide 2/2</div></div>"}],"contrastReport":{"score":50,"status":"fail","totalElements":6,"passedElements":3,"failedElements":3,"slideResults":[{"slideNumber":1,"title":"Apple Tree","elementsCount":3,"issuesCount":0,"hasBgImage":false,"hasOverlay":false,"issues":[]},{"slideNumber":2,"title":"Banana Plant","elementsCount":6,"issuesCount":3,"hasBgImage":true,"hasOverlay":false,"issues":[{"element":"<h1>","text":"Banana Plant","ratio":16.32,"targetRatio":3,"isPass":false,"issue":"Text is placed over background image/gradient without dark overlay or text-shadow protection.","recommendation":"Use high-contrast color (e.g., #FFFFFF on dark or #1A202C on light) or add a backdrop overlay."},{"element":"<p>","text":"Technically a giant herb, not a tree....","ratio":16.32,"targetRatio":4.5,"isPass":false,"issue":"Text is placed over background image/gradient without dark overlay or text-shadow protection.","recommendation":"Use high-contrast color (e.g., #FFFFFF on dark or #1A202C on l